/* The compiled help manual (generated by tools/gen_help.py from help/ *.txt into
 * $(BUILD)/gen/help_gen.c; placed in internal flash bank 2 on hardware).
 *
 * Where the compressed topics are (docs/QSPI_CONTENT.md): with
 * help_all_resident (the CONTENT=internal build) all of them are in
 * help_blob; otherwise (CONTENT=qspi, the default) help_blob holds only the
 * @essentials topics (help_ess[] maps them) and the full manual is the
 * "manual" module in the QSPI (core/modstore.h), a self-contained payload
 * with its own topic table and Huffman code (format: tools/gen_help.py,
 * "help ABI"); help_topics[] then only provides ids and titles.
 *
 * Compression format (decoded by inflate_topic() in app/help.c): every topic
 * is compressed separately (so one page can be opened without the others)
 * with LZ77 (greedy with one-step lazy matching, window up to 32 KB) and
 * one static canonical Huffman code shared by all topics (two tables:
 * literal/length symbols and distance codes; only the code lengths are
 * stored). Bits are packed MSB first. A topic's stream is a sequence of
 *   literal byte          lit symbol 0..255
 *   match (len, dist)     lit symbol 257 + len - 3, then a distance code k
 *                         and k - 1 extra bits (see HELP_NDIST)
 * ending with lit symbol 256. A deflate-like design without per-block
 * tables, which keeps the decoder to two small tables. */
#ifndef HELP_DATA_H
#define HELP_DATA_H
#include <stdint.h>

#define HELP_NLIT 321  /* literal/length alphabet: 0-255 bytes, 256 end, 257.. lengths 3..66 */
#define HELP_NDIST 16  /* distance codes: 0 -> 1, k -> 2^(k-1)+1 + (k-1 extra bits) */
#define HELP_MIN_MATCH 3
#define HELP_MAXBITS 15

/* One help page. */
typedef struct {
    uint32_t id, title;   /* offsets into help_strings */
    uint32_t off;         /* offset of the compressed topic in help_blob */
    uint32_t clen, ulen;  /* compressed / uncompressed bytes */
} help_topic_t;

/* One CATALOG entry (generated from the @cmd pages: label, the text inserted
 * before and after the cursor, and the page that documents it). */
typedef struct {
    uint32_t label, insert, suffix; /* offsets into help_strings (suffix 0 = none) */
    int32_t topic;                  /* index into help_topics */
} help_cat_t;

extern const char *const help_strings;  /* all NUL-terminated strings, concatenated */
extern const help_topic_t help_topics[]; /* sorted by id (strcmp) */
extern const uint16_t help_ntopics;
extern const help_cat_t help_catalog[];  /* sorted by label, case-insensitive */
extern const uint16_t help_ncatalog;
/* CATALOG extras, parallel to help_catalog[]: the command's summary line
 * (offset into help_strings; searched by the CATALOG filter) and its category
 * (index into help_categories[]). */
extern const uint32_t help_catalog_summary[];
extern const uint8_t help_catalog_cat[];

/* One CATALOG category (@category in the help sources, in source order; a
 * generated "Other" category without a page collects the commands that no
 * category claims). */
typedef struct {
    uint32_t title; /* offset into help_strings */
    uint32_t apps;  /* "id,id" of apps listed with it (app/registry.c ids); 0 = none */
    int32_t topic;  /* index into help_topics of its listing page, -1 = none */
} help_category_t;
extern const help_category_t help_categories[];
extern const uint16_t help_ncategories;
extern const uint8_t help_lit_lens[HELP_NLIT];  /* canonical Huffman code lengths */
extern const uint8_t help_dist_lens[HELP_NDIST];
extern const uint8_t help_blob[];        /* compressed topics in flash, back to back */
extern const uint32_t help_blob_size, help_raw_size; /* whole manual: compressed / uncompressed bytes */
extern const uint8_t help_all_resident;  /* 1: every topic is in help_blob (CONTENT=internal) */
/* An essential topic kept in flash although the manual is in the QSPI. */
typedef struct {
    uint16_t topic; /* index into help_topics */
    uint32_t off;   /* offset in help_blob */
} help_ess_t;
extern const help_ess_t help_ess[];      /* sorted by topic */
extern const uint16_t help_ness;


#endif
